import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt();
        byte[][] board = new byte[rows][];
        for (int r = 0; r < rows; r++) board[r] = next().getBytes();
        // a state is (cell, direction); a repeated state means the walk has started looping
        boolean[] seen = new boolean[rows * cols * 4], clean = new boolean[rows * cols];
        int[] di = {0, 1, 0, -1}, dj = {1, 0, -1, 0};
        int i = 0, j = 0, dir = 0, answer = 0;
        while (!seen[(i * cols + j) * 4 + dir]) {
            seen[(i * cols + j) * 4 + dir] = true;
            if (!clean[i * cols + j]) {
                clean[i * cols + j] = true;
                answer++;
            }
            int a = i + di[dir], b = j + dj[dir];
            if (a >= 0 && a < rows && b >= 0 && b < cols && board[a][b] == '.') {
                i = a;
                j = b;
            } else dir = (dir + 1) % 4;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	rows, cols := next(), next()
	board := make([]string, rows)
	for r := range board {
		sc.Scan()
		board[r] = sc.Text()
	}
	// a state is (cell, direction); a repeated state means the walk has started looping
	seen := make([]bool, rows*cols*4)
	clean := make([]bool, rows*cols)
	di, dj := [4]int{0, 1, 0, -1}, [4]int{1, 0, -1, 0}
	i, j, dir, answer := 0, 0, 0, 0
	for !seen[(i*cols+j)*4+dir] {
		seen[(i*cols+j)*4+dir] = true
		if !clean[i*cols+j] {
			clean[i*cols+j] = true
			answer++
		}
		a, b := i+di[dir], j+dj[dir]
		if a >= 0 && a < rows && b >= 0 && b < cols && board[a][b] == '.' {
			i, j = a, b
		} else {
			dir = (dir + 1) % 4
		}
	}
	fmt.Println(answer)
}
